package com.flashsale.api;
import com.flashsale.dto.*; import com.flashsale.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class PurchaseController { private final PurchaseService purchases; private final InventoryService inventory; public PurchaseController(PurchaseService purchases,InventoryService inventory){this.purchases=purchases;this.inventory=inventory;} @PostMapping("/orders") public ResponseEntity<PurchaseResponse> purchase(@RequestHeader(value="Idempotency-Key",required=false) String key,@Valid @RequestBody PurchaseRequest request){if(key==null||key.isBlank())return ResponseEntity.badRequest().body(new PurchaseResponse(null,"INVALID","Idempotency-Key header is required."));PurchaseResponse response=purchases.purchase(request,key);return ResponseEntity.status(response.status().equals("ACCEPTED")?HttpStatus.ACCEPTED:HttpStatus.OK).body(response);}@GetMapping("/inventory/{productId}") public InventoryResponse inventory(@PathVariable String productId){return new InventoryResponse(productId,inventory.available(productId));}@PutMapping("/inventory/{productId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void seed(@PathVariable String productId,@RequestParam long quantity){if(quantity<0)throw new IllegalArgumentException("quantity cannot be negative");inventory.seed(productId,quantity);} }
